async function departmentCall(action,data={}){const r=await fetch('/api/departments/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function departmentLoad(){const d=await departmentCall('status');document.getElementById('department-state').innerHTML=`<h2>Policy readiness</h2><p>Mode: ${esc(d.mode)} · Policy version: ${esc(d.policy_version||'Not supplied')}</p><p>Missing: ${esc(d.missing.join(', ')||'None; connection verification still required')}</p><p>Financial execution disabled. Identity provider disconnected. First enrollment is not available.</p>${d.departments.map(x=>`<article class="callout"><h3>${esc(x.name)}</h3><p>${esc(x.status)}</p></article>`).join('')}`;}
const beforeDepartments=render;render=function(){if(location.hash==='#departments'){document.getElementById('app').innerHTML=integratedShell('departments',heading('Department operations','Sandbox readiness and policy previews')+`<section class="card prose"><p id="department-error" role="status"></p><div id="department-state">Connect to inspect readiness.</div></section><section class="card prose"><h2>Policy preview</h2><p>Instructor-only, synthetic data. Previews never place holds, refund money or verify identity. Do not enter ID images, numbers or personal details.</p><form id="department-preview"><label>Rule<select name="action"><option value="preview_holds">Hold schedule</option><option value="preview_refund">Refund schedule</option></select></label><label>Synthetic JSON input<textarea name="payload" rows="7" required>{"invoice":{"balance_minor":1000,"due_at":0}}</textarea></label><button class="button">Preview policy decision</button></form><pre id="department-output" style="white-space:pre-wrap" aria-live="polite"></pre></section>`,model.role);bind();if(governedToken)departmentLoad().catch(e=>document.getElementById('department-error').textContent=e.message);}else beforeDepartments();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#departments"]'))nav.insertAdjacentHTML('beforeend','<a href="#departments">Department operations</a>');};
document.addEventListener('submit',async e=>{if(!['department-connect','department-preview'].includes(e.target.id))return;e.preventDefault();try{const f=new FormData(e.target);if(e.target.id==='department-connect'){governedToken=f.get('token');e.target.reset();await departmentLoad();}else{const d=JSON.parse(f.get('payload'));document.getElementById('department-output').textContent=JSON.stringify(await departmentCall(f.get('action'),{...d,synthetic:true}),null,2);}document.getElementById('department-error').textContent='';}catch(err){document.getElementById('department-error').textContent=err.message;}});
render();
